#!/bin/bash
# D63 step L9 Lean lane (2026-11-07): the full Lean build, the axiom audit of every theorem of the three L9 library
# files, the source scan, the L6Check and L5Check regressions on their committed corpora, and the L9 agreement check
# (ExecBlockCheck.lean on the W16R2 rung block), as ONE guarded job. Run through run_guarded.py (the zk60 resource
# guard, class cpu). The frame (fork_frame.bin, several MB, not committed) is regenerated by export_corpus.sh; its
# BLAKE3 is in the committed corpus.txt and the checker compares it.
WT=/Users/victorrielly/IntelligenceRegulation/.claude/worktrees/agent-abdecaa028b7cbdaf
LAKE=/Users/victorrielly/.elan/toolchains/leanprover--lean4---v4.34.1/bin/lake
OUT=$WT/results/zk60_lean_l9_20261107
O6=$WT/results/zk60_lean_l6_20261106
O5=$WT/results/zk60_lean_l5_20261106
FILES="$WT/formal/ZK60Formal/ExecBlockWire.lean $WT/formal/ZK60Formal/ExecBlockVerify.lean $WT/formal/ZK60Formal/ExecBlockFS.lean $WT/formal/ZK60Formal/ExecBlockCheck.lean"
echo "== lake build (full) =="
"$LAKE" -d "$WT/formal" build > "$OUT/full.log" 2>&1
rc=$?
echo "lake build rc $rc"
tail -n 3 "$OUT/full.log"
echo "warnings: $(grep -c 'warning' "$OUT/full.log")"
echo "errors: $(grep -c 'error' "$OUT/full.log")"
echo "sorry: $(grep -c 'sorry' "$OUT/full.log")"
echo "== axiom audit =="
python3 -I "$OUT/gen_axioms.py" "$WT/formal/ZK60Formal" "$OUT/axioms_l9.lean"
"$LAKE" -d "$WT/formal" env lean "$OUT/axioms_l9.lean" > "$OUT/axioms.log" 2>&1
arc=$?
echo "axioms rc $arc"
echo "declarations audited: $(grep -c 'depends on axioms\|does not depend on any axioms' "$OUT/axioms.log")"
echo "sorryAx: $(grep -c 'sorryAx' "$OUT/axioms.log")"
echo "ofReduceBool: $(grep -c 'ofReduceBool' "$OUT/axioms.log")"
echo "other axioms: $(grep 'depends on axioms' "$OUT/axioms.log" | grep -v -E "\[(propext|Classical.choice|Quot.sound)(, (propext|Classical.choice|Quot.sound))*\]" | wc -l | tr -d ' ')"
grep -oE "axioms: \[[^]]*\]" "$OUT/axioms.log" | sort | uniq -c
echo "== source scan of the L9 files =="
grep -n -E '\bsorry\b|\baxiom\b|native_decide|admit|maxRecDepth|maxHeartbeats|implemented_by|@\[extern|\bextern\b|bv_decide|ofReduceBool' $FILES || echo "none"
echo "== the library root imports the L9 files =="
grep -n "ZK60Formal.ExecBlock" "$WT/formal/ZK60Formal.lean" || echo "MISSING"
echo "== regression: L6Check on the committed L6 corpus =="
"$LAKE" -d "$WT/formal" env lean --run "$WT/formal/ZK60Formal/L6Check.lean" "$O6/corpus.txt" > "$OUT/l6check_regression.log" 2>&1
c6=$?
tail -n 1 "$OUT/l6check_regression.log"
echo "L6Check rc $c6"
echo "== regression: L5Check on the committed L5 corpus =="
"$LAKE" -d "$WT/formal" env lean --run "$WT/formal/ZK60Formal/L5Check.lean" "$O5/corpus.txt" > "$OUT/l5check_regression.log" 2>&1
c5=$?
tail -n 1 "$OUT/l5check_regression.log"
echo "L5Check rc $c5"
echo "== the L9 agreement check: ExecBlockCheck on the W16R2 rung block =="
# the frame (not committed) must be the corpus's: its BLAKE3 is checked by the checker itself
ls -l "$OUT/fork_frame.bin"
# the decoder's readers recurse once per word of a clear vector (16,664 at W16R2): a larger stack for the interpreter
ulimit -s 65520
"$LAKE" -d "$WT/formal" env lean --run "$WT/formal/ZK60Formal/ExecBlockCheck.lean" "$OUT/corpus.txt" "$OUT/fork_frame.bin" > "$OUT/l9check_full.log" 2>&1
c9=$?
tail -n 1 "$OUT/l9check_full.log"
echo "ExecBlockCheck rc $c9"
echo "== negative control: six single changes to the corpus =="
python3 -I "$OUT/mutate_corpus.py" "$OUT/corpus.txt" "$OUT/corpus_mutated.txt"
"$LAKE" -d "$WT/formal" env lean --run "$WT/formal/ZK60Formal/ExecBlockCheck.lean" "$OUT/corpus_mutated.txt" "$OUT/fork_frame.bin" > "$OUT/negative_control.log" 2>&1
echo "negative control rc $? (nonzero expected)"
tail -n 1 "$OUT/negative_control.log"
grep "^FAILED" "$OUT/negative_control.log"
gn=1
grep -q '^ExecBlockCheck: [0-9]* checks, 6 failed$' "$OUT/negative_control.log" && gn=0
g6=1
grep -q '^L6Check: 1206 checks, 0 failed$' "$OUT/l6check_regression.log" && g6=0
g5=1
grep -q '^L5Check: 5553 checks, 0 failed$' "$OUT/l5check_regression.log" && g5=0
g9=1
grep -q '^ExecBlockCheck: [0-9]* checks, 0 failed$' "$OUT/l9check_full.log" && g9=0
echo "verdicts: L6 $g6, L5 $g5, L9 $g9, negative control $gn (0 = as required)"
[ $rc -eq 0 ] && [ $arc -eq 0 ] && [ $c6 -eq 0 ] && [ $c5 -eq 0 ] && [ $c9 -eq 0 ] && [ $g6 -eq 0 ] && [ $g5 -eq 0 ] && [ $g9 -eq 0 ] && [ $gn -eq 0 ]
